import{_ as a,o,c as i,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"11.2 接地与接零保护","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-2-jie-di-yu-jie-ling-bao-hu.md","filePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-2-jie-di-yu-jie-ling-bao-hu.md","lastUpdated":1793096070000}'),e={name:"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-2-jie-di-yu-jie-ling-bao-hu.md"};function r(n,t,s,d,u,g){return o(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_11-2-接地与接零保护" tabindex="-1">11.2 接地与接零保护 <a class="header-anchor" href="#_11-2-接地与接零保护" aria-label="Permalink to &quot;11.2 接地与接零保护&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;接地&quot;和&quot;接零&quot;是低压配电两大安全保护,常考且易混。这一节先分清各种&quot;接地&quot;的名词,再重点讲<strong>保护接地</strong>和<strong>保护接零</strong>的原理与区别。</p><h2 id="一、各种接地的分类" tabindex="-1">一、各种接地的分类 <a class="header-anchor" href="#一、各种接地的分类" aria-label="Permalink to &quot;一、各种接地的分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接地类型</th><th>干什么的</th></tr></thead><tbody><tr><td><strong>工作接地</strong></td><td>电源中性点接地,保证系统正常运行(如变压器中性点直接接地)</td></tr><tr><td><strong>保护接地</strong></td><td>设备金属外壳接地,防外壳带电伤人</td></tr><tr><td><strong>保护接零</strong></td><td>设备金属外壳接保护零线(PE),TN 系统用</td></tr><tr><td><strong>重复接地</strong></td><td>保护零线(或中性线)在配电中途多处再次接地</td></tr><tr><td><strong>防雷接地</strong></td><td>防雷装置入地泄放雷电流</td></tr><tr><td><strong>屏蔽接地</strong></td><td>屏蔽层接地,防干扰</td></tr></tbody></table><blockquote><p>💡 <strong>工作接地保&quot;运行&quot;,保护接地保&quot;人身&quot;</strong>——一个为电,一个为人。</p></blockquote><h2 id="二、保护接地-tt-系统的做法" tabindex="-1">二、保护接地(TT 系统的做法) <a class="header-anchor" href="#二、保护接地-tt-系统的做法" aria-label="Permalink to &quot;二、保护接地(TT 系统的做法)&quot;">​</a></h2><p><strong>把设备金属外壳直接与大地(接地极)连接</strong>:</p><ul><li>设备漏电 → 外壳带电 → 电流经外壳流人地(外壳与大地电位近似相等);</li><li>人接触外壳时,由于人与外壳并联但人体电阻远大于接地电阻,通过人体的电流很小,得到保护;</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备外壳 ──► 接地极 ──► 大地(泄流)</span></span>
<span class="line"><span>        ──► 人(并联,电流很小)</span></span></code></pre></div><p>用于<strong>电源中性点不接地或独立接地的系统(TT、IT)</strong>。</p><h2 id="三、保护接零-tn-系统的做法" tabindex="-1">三、保护接零(TN 系统的做法) <a class="header-anchor" href="#三、保护接零-tn-系统的做法" aria-label="Permalink to &quot;三、保护接零(TN 系统的做法)&quot;">​</a></h2><p><strong>把设备金属外壳接保护零线(PE 线)</strong>:</p><ul><li>设备漏电 → 外壳 → PE 线 → 中性点 → 形成<strong>单相短路</strong>;</li><li>短路电流很大 → 促使保护装置(熔断器/断路器)<strong>迅速跳闸</strong>,切断故障设备;</li><li>故障设备失电,人就不触电。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备漏电 ──► 外壳 ──► PE线 ──► 短路大电流 ──► 保护装置跳闸停电</span></span></code></pre></div><p>用于<strong>电源中性点直接接地的系统(TN 系统)</strong>。</p><blockquote><p>💡 通俗对比:<strong>接地是&quot;把电压拉低让人安全&quot;,接零是&quot;把漏电变成短路让开关跳闸&quot;</strong>。</p></blockquote><h2 id="四、接零与接地不能混用-必考" tabindex="-1">四、接零与接地不能混用(必考) <a class="header-anchor" href="#四、接零与接地不能混用-必考" aria-label="Permalink to &quot;四、接零与接地不能混用(必考)&quot;">​</a></h2><p>在同一低压电网(同一变压器供电范围)内:</p><ul><li><strong>不允许一部分设备接零、一部分设备接地</strong>;</li><li>否则,接地的设备漏电时,外壳经大地→电源中性点形成回路,使<strong>整个接零系统的零线电位升高</strong>,所有接零设备外壳都带上危险电压。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>同一低压电网内,保护接零和保护接地不能混用</strong>。</p></blockquote><h2 id="五、重复接地" tabindex="-1">五、重复接地 <a class="header-anchor" href="#五、重复接地" aria-label="Permalink to &quot;五、重复接地&quot;">​</a></h2><ul><li>在 TN 系统中,保护零线(或 PEN 线)除中性点接地外,<strong>在配电线路的中段、末端再接地</strong>;</li><li>好处:PEN(零)线断线时,断点之后的设备外壳仍经重复接地与大地连接,降低触电危险。</li></ul><blockquote><p>💡 通俗理解:零线&quot;一路走一路补接地&quot;,防止零线断了之后后面的设备外壳&quot;悬空带电&quot;。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 工作接地=电源中性点接地;保护接地/接零=设备外壳保护。</li><li>✅ <strong>保护接地</strong>:外壳直接入地,用于 TT/IT;</li><li>✅ <strong>保护接零</strong>:外壳接 PE 线,漏电变短路促跳闸,用于 TN。</li><li>✅ <strong>接零与接地不能混用</strong>。</li><li>⚠️ 易混点:接零(接中性线回路,靠跳闸)与接地(接大地,靠限流)原理不同、系统不同。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>接地分工作、保护、重复、防雷等多种,作用各不相同。</li><li>保护接地把漏电引向大地;保护接零把漏电变短路跳闸。</li><li>TN 系统接零、TT 系统接地,同一电网内不能混用。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)保护接地是把设备金属外壳直接与大地相连。( )</li><li>(单选)保护接零(接零保护)用于()系统。 A. IT　B. TT　C. TN　D. 中性点不接地系统</li><li>(判断)同一低压电网内,可以一部分设备保护接地、一部分设备保护接零。( )</li><li>(单选)电源中性点直接接地以保证系统正常运行,这种接地称为()。 A. 保护接地　B. 工作接地　C. 防雷接地　D. 屏蔽接地</li><li>(判断)保护接零的原理是:设备漏电时形成单相短路,促使保护装置迅速切断电源。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。保护接地是外壳接大地(独立接地极)。</li><li><strong>C</strong>。保护接零用于电源中性点直接接地的 TN 系统。</li><li><strong>×</strong>。同一电网内严禁接零与接地混用。</li><li><strong>B</strong>。中性点接地是工作接地。</li><li><strong>√</strong>。接零把漏电变短路,促跳闸。</li></ol></details>`,31)])])}const p=a(e,[["render",r]]);export{c as __pageData,p as default};
